import { createGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/courier-d2-1/bot.mjs';
import assert from 'node:assert/strict';
const d = s => new Date(s);
const LA='America/Los_Angeles', BE='Europe/Berlin';
let g = createGate();
// LA midnight = 08:00Z (PDT, Oct). 
let r1 = g.request({userId:'u',timeZone:LA,category:'promo',now:d('2026-10-21T07:00:00Z')}); // Oct 21 00:00 PDT? 07Z=00:00 PDT
assert(r1.allowed && r1.rule==='' && r1.id);
assert.equal(g.request({userId:'u',timeZone:LA,category:'promo',now:d('2026-10-21T08:59:00Z')}).rule,'min-gap');
assert(g.request({userId:'u',timeZone:LA,category:'promo',now:d('2026-10-21T09:00:00Z')}).allowed);
assert(g.request({userId:'u',timeZone:LA,category:'promo',now:d('2026-10-21T11:00:00Z')}).allowed);
assert.equal(g.request({userId:'u',timeZone:LA,category:'promo',now:d('2026-10-21T14:00:00Z')}).rule,'daily-cap');
// security unaffected
assert(g.request({userId:'u',timeZone:LA,category:'security',now:d('2026-10-21T14:00:00Z')}).allowed);
// next local day (07:00Z Oct 22 is 00:00 PDT) but 2h gap fine
assert(g.request({userId:'u',timeZone:LA,category:'promo',now:d('2026-10-22T07:00:00Z')}).allowed);
// other user independent
assert(g.request({userId:'v',timeZone:BE,category:'promo',now:d('2026-10-21T14:00:00Z')}).allowed);
// cancel frees slot
g = createGate();
const a=g.request({userId:'u',timeZone:BE,category:'promo',now:d('2026-10-21T10:00:00Z')});
g.cancel(a.id); g.cancel(a.id); g.cancel('nope');
assert(g.request({userId:'u',timeZone:BE,category:'promo',now:d('2026-10-21T10:30:00Z')}).allowed);
// Berlin midnight boundary: 21:59Z Oct 21 is 23:59 CEST; 22:00Z is Oct 22
g = createGate();
for (const t of ['2026-10-21T10:00Z','2026-10-21T12:00Z','2026-10-21T21:59Z']) assert(g.request({userId:'u',timeZone:BE,category:'promo',now:d(t)}).allowed);
assert(g.request({userId:'u',timeZone:BE,category:'promo',now:d('2026-10-21T22:00Z')}).allowed===true); // new day, gap ok
// DST end Oct 25 2026 Berlin: day is 25h, still 3 cap
assert.equal(createGate().request({userId:'u',timeZone:'Bad/Zone',category:'promo',now:d('2026-10-21T10:00Z')}).rule,'invalid-time-zone');
console.log('ok');
